css:
.radial-menu-container {
  /* Playful Variables */
  --ink: #1f2937;
  --c-blue: #89b4ff;
  --c-red: #ff8989;
  --c-yellow: #ffdf70;
  --c-green: #89ffb4;

  /* Irregular Doodle Radii for a hand-drawn look */
  --radius-1: 50% 45% 55% 40% / 55% 45% 50% 50%;
  --radius-2: 40% 60% 45% 55% / 50% 55% 40% 60%;
  --radius-3: 55% 45% 50% 55% / 45% 55% 60% 40%;

  position: relative;
  width: min(100%, 420px);
  aspect-ratio: 1 / 1;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-family: "Comic Sans MS", "Chalkboard SE", "Marker Felt", sans-serif;

  /* Background removed as requested */
  background: transparent;
  padding: 20px;
  box-sizing: border-box;
  overflow: hidden;
}

.radial-menu-container .doodle-decorations {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 0;
  opacity: 0;
  transform: scale(0.9);
  transition: all 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.radial-menu-container:has(.menu-toggle:checked) .doodle-decorations {
  opacity: 1;
  transform: scale(1);
}

.radial-menu-container .menu-toggle {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

/* CENTER DOODLE BUTTON */
.radial-menu-container .center-icon {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 4.4em;
  height: 4.4em;
  transform: translate(-50%, -50%);

  background: #ffffff;
  border: 3.5px solid var(--ink);
  border-radius: 45% 55% 45% 55% / 55% 45% 55% 45%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 100;

  /* Solid comic book drop shadow */
  box-shadow: 5px 5px 0px var(--ink);
  transition:
    transform 0.2s cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 0.2s ease;
}

.radial-menu-container .center-icon:hover {
  transform: translate(-50%, -50%) scale(1.05) rotate(-3deg);
  box-shadow: 7px 7px 0px var(--c-blue);
}

.radial-menu-container .center-icon:active {
  transform: translate(-50%, -50%) scale(0.95);
  box-shadow: 2px 2px 0px var(--ink);
}

.radial-menu-container .center-icon svg {
  width: 2.6em;
  height: 2.6em;
  transition: transform 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.radial-menu-container .menu-toggle:checked ~ .center-icon svg {
  transform: rotate(180deg) scale(0.9);
}

/* MARKER STROKE LINES */
.radial-menu-container .connection-lines {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
  overflow: visible;
}

.radial-menu-container .line {
  fill: none;
  stroke-width: 4.5;
  stroke-linecap: round;
  opacity: 0;
  stroke-dasharray: 200;
  stroke-dashoffset: 200;
  /* Apply SVG filter for sketchy hand-drawn waviness */
  filter: url(#handDrawn) drop-shadow(2px 2px 0px rgba(0, 0, 0, 0.1));
  transition:
    opacity 0.3s ease,
    stroke-dashoffset 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Assign alternating pastel ink colors to lines */
.radial-menu-container .line-1 {
  stroke: var(--c-red);
}
.radial-menu-container .line-2 {
  stroke: var(--c-blue);
}
.radial-menu-container .line-3 {
  stroke: var(--c-yellow);
}
.radial-menu-container .line-4 {
  stroke: var(--c-green);
}
.radial-menu-container .line-5 {
  stroke: var(--c-red);
}
.radial-menu-container .line-6 {
  stroke: var(--c-blue);
}
.radial-menu-container .line-7 {
  stroke: var(--c-yellow);
}
.radial-menu-container .line-8 {
  stroke: var(--c-green);
}

.radial-menu-container .menu-toggle:checked ~ .connection-lines .line {
  opacity: 1;
  stroke-dashoffset: 0;
}

.radial-menu-container .menu-toggle:checked ~ .connection-lines .line-1 {
  transition-delay: 0.05s;
}
.radial-menu-container .menu-toggle:checked ~ .connection-lines .line-2 {
  transition-delay: 0.1s;
}
.radial-menu-container .menu-toggle:checked ~ .connection-lines .line-3 {
  transition-delay: 0.15s;
}
.radial-menu-container .menu-toggle:checked ~ .connection-lines .line-4 {
  transition-delay: 0.2s;
}
.radial-menu-container .menu-toggle:checked ~ .connection-lines .line-5 {
  transition-delay: 0.25s;
}
.radial-menu-container .menu-toggle:checked ~ .connection-lines .line-6 {
  transition-delay: 0.3s;
}
.radial-menu-container .menu-toggle:checked ~ .connection-lines .line-7 {
  transition-delay: 0.35s;
}
.radial-menu-container .menu-toggle:checked ~ .connection-lines .line-8 {
  transition-delay: 0.4s;
}

/* OUTER STICKER BUTTONS */
.radial-menu-container .menu-item {
  position: absolute;
  left: 50%;
  top: 50%;
  opacity: 0;
  transform: translate(-50%, -50%) scale(0) rotate(-20deg);
  transition:
    opacity 0.35s ease,
    top 0.55s cubic-bezier(0.68, -0.55, 0.265, 1.55),
    left 0.55s cubic-bezier(0.68, -0.55, 0.265, 1.55),
    transform 0.55s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  z-index: 10;
}

.radial-menu-container .menu-toggle:checked ~ .menu-item {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1) rotate(0deg);
}

/* Positioning mapping */
.radial-menu-container .menu-toggle:checked ~ .item-1 {
  top: 15%;
  left: 50%;
  transition-delay: 0.08s;
}
.radial-menu-container .menu-toggle:checked ~ .item-2 {
  top: 25.25%;
  left: 74.75%;
  transition-delay: 0.13s;
}
.radial-menu-container .menu-toggle:checked ~ .item-3 {
  top: 50%;
  left: 85%;
  transition-delay: 0.18s;
}
.radial-menu-container .menu-toggle:checked ~ .item-4 {
  top: 74.75%;
  left: 74.75%;
  transition-delay: 0.23s;
}
.radial-menu-container .menu-toggle:checked ~ .item-5 {
  top: 85%;
  left: 50%;
  transition-delay: 0.28s;
}
.radial-menu-container .menu-toggle:checked ~ .item-6 {
  top: 74.75%;
  left: 25.25%;
  transition-delay: 0.33s;
}
.radial-menu-container .menu-toggle:checked ~ .item-7 {
  top: 50%;
  left: 15%;
  transition-delay: 0.38s;
}
.radial-menu-container .menu-toggle:checked ~ .item-8 {
  top: 25.25%;
  left: 25.25%;
  transition-delay: 0.43s;
}

/* Base Sticker Design */
.radial-menu-container .icon-circle {
  position: relative;
  width: 3.2em;
  height: 3.2em;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border: 3px solid var(--ink);
  padding: 0;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

/* Randomize Borders and Shadows for Doodle Look */
.radial-menu-container .item-1 .icon-circle,
.radial-menu-container .item-5 .icon-circle {
  border-radius: var(--radius-1);
  box-shadow: 4px 4px 0px var(--c-red);
}
.radial-menu-container .item-2 .icon-circle,
.radial-menu-container .item-6 .icon-circle {
  border-radius: var(--radius-2);
  box-shadow: -4px 4px 0px var(--c-blue);
}
.radial-menu-container .item-3 .icon-circle,
.radial-menu-container .item-7 .icon-circle {
  border-radius: var(--radius-3);
  box-shadow: 4px -4px 0px var(--c-yellow);
}
.radial-menu-container .item-4 .icon-circle,
.radial-menu-container .item-8 .icon-circle {
  border-radius: var(--radius-1);
  box-shadow: -4px -4px 0px var(--c-green);
}

/* Fun Hover Animations */
@keyframes sticker-wiggle {
  0% {
    transform: scale(1.15) rotate(-6deg);
  }
  50% {
    transform: scale(1.15) rotate(6deg);
  }
  100% {
    transform: scale(1.15) rotate(-6deg);
  }
}

.radial-menu-container .icon-circle:hover {
  animation: sticker-wiggle 0.4s ease-in-out infinite;
  box-shadow: 6px 6px 0px var(--ink) !important;
  z-index: 20;
}

.radial-menu-container .icon-circle svg {
  width: 1.8em;
  height: 1.8em;
}

/* Comic Book Style Tooltips */
.radial-menu-container .icon-circle::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: 130%;
  left: 50%;
  transform: translateX(-50%) translateY(10px) rotate(-3deg) scale(0.8);
  background: #ffffff;
  color: var(--ink);
  border: 2px solid var(--ink);
  border-radius: 12px 12px 12px 0;
  padding: 0.4em 0.8em;
  font-size: 0.85em;
  font-weight: bold;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  box-shadow: 3px 3px 0px var(--c-yellow);
  transition:
    opacity 0.2s ease,
    transform 0.25s cubic-bezier(0.68, -0.55, 0.265, 1.55);
  z-index: 999;
}

.radial-menu-container .icon-circle:hover::after,
.radial-menu-container .icon-circle:focus-visible::after {
  opacity: 1;
  transform: translateX(-50%) translateY(0) rotate(-3deg) scale(1);
}

/* Floating Idle Animation */
@keyframes subtle-float {
  0%,
  100% {
    transform: translate(-50%, -50%) translateY(0);
  }
  50% {
    transform: translate(-50%, -50%) translateY(-5px);
  }
}

.radial-menu-container .menu-toggle:checked ~ .item-1 {
  animation: subtle-float 3s ease-in-out infinite 0.1s;
}
.radial-menu-container .menu-toggle:checked ~ .item-2 {
  animation: subtle-float 3.2s ease-in-out infinite 0.3s;
}
.radial-menu-container .menu-toggle:checked ~ .item-3 {
  animation: subtle-float 2.8s ease-in-out infinite 0.5s;
}
.radial-menu-container .menu-toggle:checked ~ .item-4 {
  animation: subtle-float 3.5s ease-in-out infinite 0.2s;
}
.radial-menu-container .menu-toggle:checked ~ .item-5 {
  animation: subtle-float 3.1s ease-in-out infinite 0.4s;
}
.radial-menu-container .menu-toggle:checked ~ .item-6 {
  animation: subtle-float 2.9s ease-in-out infinite 0.6s;
}
.radial-menu-container .menu-toggle:checked ~ .item-7 {
  animation: subtle-float 3.4s ease-in-out infinite 0.1s;
}
.radial-menu-container .menu-toggle:checked ~ .item-8 {
  animation: subtle-float 3.3s ease-in-out infinite 0.7s;
}

@media (max-width: 480px) {
  .radial-menu-container {
    font-size: 11px;
  }
  .radial-menu-container .icon-circle::after {
    display: none;
  }
}
